/* ============ dicionário de códigos ============ */
const CODE_INFO = {
  P:   { label: "Presente",                color: "#3fb96b", bg: "rgba(63,185,107,.14)",  group: "present" },
  F:   { label: "Falta injustificada",     color: "#ef5b62", bg: "rgba(239,91,98,.14)",   group: "absent"  },
  FJ:  { label: "Falta justificada",       color: "#9d7bf0", bg: "rgba(157,123,240,.14)", group: "absent"  },
  AM:  { label: "Atestado médico",         color: "#d9902b", bg: "rgba(217,144,43,.14)",  group: "absent"  },
  AF:  { label: "Afastamento",             color: "#e0484d", bg: "rgba(224,72,77,.14)",   group: "absent"  },
  AL:  { label: "Afastamento longo",       color: "#c23640", bg: "rgba(194,54,64,.16)",   group: "absent"  },
  AB:  { label: "Abandono",                color: "#ff5c5c", bg: "rgba(255,92,92,.14)",   group: "absent"  },
  BH:  { label: "Banco de Horas",          color: "#6a6af0", bg: "rgba(106,106,240,.14)", group: "planned" },
  FO:  { label: "Folga",                   color: "#2fb4b8", bg: "rgba(47,180,184,.14)",  group: "planned" },
  FE:  { label: "Férias",                  color: "#40c07a", bg: "rgba(64,192,122,.14)",  group: "planned" },
  DSR: { label: "Descanso Semanal",        color: "#3d9a72", bg: "rgba(61,154,114,.14)",  group: "dsr"     },
  DV:  { label: "Deslig. voluntário",      color: "#8b93a1", bg: "rgba(139,147,161,.14)", group: "off"     },
  DF:  { label: "Deslig. forçado",         color: "#d06a72", bg: "rgba(208,106,114,.14)", group: "off"     },
  DP:  { label: "Deslig. programado",      color: "#5a9bd4", bg: "rgba(90,155,212,.14)",  group: "off"     },
  "":  { label: "Sem registro",            color: "#5d6a7d", bg: "rgba(93,106,125,.12)",  group: "none"    },
};
const codeInfo = (c) => CODE_INFO[c] || { label: c, color: "#c8cede", bg: "rgba(200,206,222,.12)", group: "other" };

const WEEKDAYS = ["DOM", "SEG", "TER", "QUA", "QUI", "SEX", "SÁB"];

/* ============ parse: CSV de escala (modelo 2) ============ */
function parseEscalaCsv(text) {
  const lines = text.replace(/^\uFEFF/, "").split(/\r?\n/);
  const sections = [];
  let cur = null;
  let curWeek = null;
  const weekRe = /^(.*?)\s*\((\d{2})\/(\d{2})\s*a\s*(\d{2})\/(\d{2})\)$/;

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i].trim();
    if (!raw) { curWeek = null; continue; }
    const cells = raw.split(";").map((c) => c.trim());

    if (cells.length === 1 && !raw.includes(";")) {
      // possível título de seção (linha seguinte deve ser "Series ativas")
      const next = (lines[i + 1] || "").trim();
      if (/^series?\s+ativas/i.test(next)) {
        const parts = raw.split(" - ");
        cur = { title: raw, name: parts[parts.length - 1] || raw, series: [], weeks: [] };
        sections.push(cur);
        curWeek = null;
      }
      continue;
    }
    if (!cur) continue;

    if (/^series?\s+ativas/i.test(cells[0])) {
      cur.series = (cells[1] || "").split("/").map((s) => s.trim()).filter(Boolean);
      continue;
    }

    const wm = cells[0].match(weekRe);
    if (wm && cells[1] === "DOM") {
      curWeek = {
        label: cells[0],
        shortLabel: wm[1].trim(),
        start: { d: +wm[2], m: +wm[3] },
        end: { d: +wm[4], m: +wm[5] },
        rows: {},   // série -> [7 valores: "DSR" | número]
        totals: null,
      };
      cur.weeks.push(curWeek);
      continue;
    }
    if (!curWeek) continue;

    if (/^[A-Z]$/.test(cells[0])) {
      curWeek.rows[cells[0]] = cells.slice(1, 8).map((v) => (v.toUpperCase() === "DSR" ? "DSR" : Number(v)));
    } else if (/^total$/i.test(cells[0])) {
      curWeek.totals = cells.slice(1, 8).map(Number);
    }
  }
  return sections.filter((s) => s.weeks.length);
}

/* ============ unificação de turnos (AM+PM) guiada pela planilha 1 ============ */
// base do nome da seção (título sem o sufixo do turno). ex.: "Escala Julho - Varginha - AM" -> "Escala Julho - Varginha"
const sectionBase = (title) => title.replace(/\s*-\s*[^-]+$/, "").trim();
const shiftOf = (name) => {
  const u = String(name).toUpperCase().trim();
  if (u === "AM") return "AM";
  if (u === "PM") return "PM";
  return null; // SD e demais não são turnos mescláveis
};

// a planilha 1 distingue AM/PM? (procura marcadores de turno na coluna Turno)
function empsAreShiftAware(emps) {
  if (!emps) return false;
  return emps.some((e) => /(^|[^A-Z])(AM|PM)([^A-Z]|$)/.test(String(e[1]).toUpperCase()));
}

// mescla seções de turno (AM + PM) somando as metas por série/dia; DSR só permanece se for DSR em ambos
function mergeShiftSections(base, secs) {
  const series = secs.find((s) => s.series.length)?.series.slice() || [];
  const weeksCount = Math.max(...secs.map((s) => s.weeks.length));
  const weeks = [];
  for (let wi = 0; wi < weeksCount; wi++) {
    const refW = secs.map((s) => s.weeks[wi]).find(Boolean);
    if (!refW) continue;
    const rows = {};
    series.forEach((se) => {
      rows[se] = Array.from({ length: 7 }, (_, di) => {
        let sum = 0, allDsr = true, any = false;
        secs.forEach((s) => {
          const v = s.weeks[wi]?.rows[se]?.[di];
          if (v === undefined) return;
          any = true;
          if (typeof v === "number") { sum += v; allDsr = false; }
        });
        if (!any) return undefined;
        return allDsr ? "DSR" : sum;
      });
    });
    weeks.push({ ...refW, rows, totals: null });
  }
  return { title: `${base} - AM+PM`, name: "AM+PM", series, weeks, merged: true };
}

// lista de seções apresentável: mescla AM+PM (mantendo SD à parte) quando a planilha 1 não distingue turno
function unifySections(escSections, shiftAware) {
  if (!escSections) return null;
  if (shiftAware) return escSections;
  const groups = new Map(); // base -> { am, pm, others: [] }
  escSections.forEach((s) => {
    const base = sectionBase(s.title);
    const g = groups.get(base) || { base, am: null, pm: null, others: [] };
    const sh = shiftOf(s.name);
    if (sh === "AM") g.am = s;
    else if (sh === "PM") g.pm = s;
    else g.others.push(s);
    groups.set(base, g);
  });
  const out = [];
  for (const g of groups.values()) {
    if (g.am && g.pm) out.push(mergeShiftSections(g.base, [g.am, g.pm]));
    else { if (g.am) out.push(g.am); if (g.pm) out.push(g.pm); }
    g.others.forEach((o) => out.push(o));
  }
  return out;
}

/* ============ parse: aba de absenteísmo (modelo 1) ============ */
function parseAbsSheet(ws) {
  const grid = XLSX.utils.sheet_to_json(ws, { header: 1, defval: "" });
  let hi = -1;
  for (let i = 0; i < Math.min(grid.length, 12); i++) {
    const row = grid[i].map((c) => String(c));
    if (row.some((c) => /^nome$/i.test(c.trim())) && row.some((c) => /^turno$/i.test(c.trim()))) { hi = i; break; }
  }
  if (hi < 0) return { error: "Não encontrei as colunas 'Nome' e 'Turno' nesta aba." };
  const header = grid[hi].map((c) => String(c));
  const idx = (re) => header.findIndex((c) => re.test(c.trim()));
  const nameI = idx(/^nome$/i), turnoI = idx(/^turno$/i), cargoI = idx(/^cargo$/i), lidI = idx(/^lideran/i);
  const dayCols = {};
  header.forEach((h, i) => {
    const m = h.trim().match(/^(\d{1,2})\s/);
    if (m) dayCols[+m[1]] = i;
  });
  if (!Object.keys(dayCols).length) return { error: "Não encontrei colunas de dias (ex.: '1 Qua') nesta aba." };

  const emps = [];
  for (let r = hi + 1; r < grid.length; r++) {
    const row = grid[r];
    const nome = String(row[nameI] || "").trim();
    if (!nome) continue;
    const days = [];
    for (let d = 1; d <= 31; d++) days.push(dayCols[d] != null ? String(row[dayCols[d]] || "").trim().toUpperCase() : "");
    emps.push([nome, String(row[turnoI] || "").trim().toUpperCase() || "?", String(cargoI >= 0 ? row[cargoI] : "").trim(), String(lidI >= 0 ? row[lidI] : "").trim(), days.join("|")]);
  }
  return { emps };
}

/* ============ datas ============ */
function buildWeekDates(week, year) {
  const start = new Date(year, week.start.m - 1, week.start.d);
  return Array.from({ length: 7 }, (_, i) => {
    const dt = new Date(start);
    dt.setDate(start.getDate() + i);
    return { d: dt.getDate(), m: dt.getMonth() + 1 };
  });
}
function detectMainMonth(section, year) {
  const freq = {};
  section.weeks.forEach((w) => buildWeekDates(w, year).forEach(({ m }) => (freq[m] = (freq[m] || 0) + 1)));
  return +Object.entries(freq).sort((a, b) => b[1] - a[1])[0][0];
}

/* ============ cruzamento escala × pessoas ============ */
function buildCell(escVal, date, mainMonth, serie, emps) {
  const inMonth = date.m === mainMonth && date.d >= 1 && date.d <= 31;
  const people = [];
  const counts = { present: 0, absent: 0, planned: 0, dsr: 0, off: 0, none: 0, other: 0 };
  if (inMonth) {
    for (const e of emps) {
      if (e[1] !== serie) continue;
      const code = e[4].split("|")[date.d - 1] || "";
      const g = codeInfo(code).group;
      counts[g] = (counts[g] || 0) + 1;
      people.push({ nome: e[0], cargo: e[2], lider: e[3], code });
    }
  }
  const alerts = [];
  if (!inMonth) {
    alerts.push({ sev: "muted", msg: "Fora do mês da planilha — sem dados de presença." });
  } else if (escVal === "DSR") {
    if (counts.present > 0) alerts.push({ sev: "red", msg: `${counts.present} pessoa(s) marcadas como presentes em dia de DSR da série — não faz sentido.` });
    if (counts.absent > 0) alerts.push({ sev: "info", msg: `${counts.absent} ausência(s) registradas em dia de DSR da série.` });
  } else if (typeof escVal === "number") {
    const active = people.length - counts.off - counts.none;
    if (active === 0 && people.length === 0) {
      alerts.push({ sev: "red", msg: "Nenhuma pessoa encontrada nesta série na planilha." });
    } else {
      const gap = counts.present - escVal;
      if (gap < 0) alerts.push({ sev: gap <= -Math.ceil(escVal * 0.2) ? "red" : "amber", msg: `Faltam ${-gap} para a meta de ${escVal} (presentes: ${counts.present}).` });
      if (gap > 0) alerts.push({ sev: "blue", msg: `Excede a meta de ${escVal} em ${gap} pessoa(s) (presentes: ${counts.present}).` });
      if (counts.dsr > 0) alerts.push({ sev: "info", msg: `${counts.dsr} com DSR individual em dia de trabalho da série.` });
    }
  }
  // total de pessoas da série no dia (contando DSR, pois a escala já prevê as folgas)
  const total = people.length;
  // absenteísmo em relação ao programado na escala (ex.: 100 previstos, 10 faltas = 10%)
  const absBase = typeof escVal === "number" ? escVal : 0;
  const absRate = absBase > 0 ? counts.absent / absBase : null;
  return { escVal, date, serie, inMonth, people, counts, alerts, total, absBase, absRate };
}

/* ============ paleta / tema (inspirado no 2º print) ============ */
